import {itemName} from './guide.js';

export const equipmentNeeds=mission=>mission.recommendedEquipment.map(row=>typeof row==='string'?row:row.name||row.description||row.text).filter(Boolean);
export function ownFarmTotals(progress,missionId,difficulty){
 const rows=Object.values(progress.farmRuns).filter(row=>row.missionId===missionId&&row.difficulty===difficulty);
 return rows.reduce((sum,row)=>({runs:sum.runs+row.runs,minutes:sum.minutes+row.minutes,credits:sum.credits+row.yield.credits}),{runs:0,minutes:0,credits:0});
}
export function routeWeapons(route,weapons){return route.weaponIds.map(id=>weapons.find(w=>w.id===id)).filter(Boolean);}
export function weaponAdviceHtml(note,{escape,sourceLinks=()=>''}){return note?`<div class="weapon-usage"><h4>${escape(note.role)}</h4><p><strong>適合：</strong>${escape(note.good)}</p><p><strong>換槍前先看：</strong>${escape(note.avoid)}</p><p class="unknown">來源心得整理，未逐關實機驗證。</p>${sourceLinks(note.sourceIds)}</div>`:'';}

export function adviceHtml({data,mission,missions,weapons,progress,escape,option,button,sourceLinks}){
 const weaponLink=w=>`<a href="?view=weapons#weapon-${escape(w.id)}" data-weapon-link="${escape(w.id)}">${escape(itemName(w))}</a>`;
 const routeHtml=route=>{
  const rows=routeWeapons(route,weapons),owned=rows.filter(w=>progress.weapons[w.id]?.purchased).length;
  return `<details class="advice-route" id="route-${escape(route.id)}"><summary><small>${escape(route.stage)}</small><strong>${escape(route.title)}</strong><span>持有 ${owned}/${rows.length}</span></summary><div class="advice-route-body"><ol>${route.steps.map(step=>`<li>${escape(step)}</li>`).join('')}</ol><p class="warning">${escape(route.caution)}</p><div class="advice-weapon-list">${rows.map(w=>`<div><div>${weaponLink(w)}<small>${escape(w.unlockCondition)}</small><small>Credits ${w.price.credits?.toLocaleString()??'待查'} · 紅 ${w.price.red??'待查'} · 藍 ${w.price.blue??'待查'} · 黃 ${w.price.yellow??'待查'}</small></div><label class="check-label"><input type="checkbox" id="advice-${escape(w.id)}-purchased" data-weapon="${escape(w.id)}" data-key="purchased" ${progress.weapons[w.id]?.purchased?'checked':''}>持有</label></div>`).join('')}</div><div class="actions">${route.missionIds.map(id=>button('roadmap',id.toUpperCase(),id)).join('')}${route.id==='drones'?button('drones','找 Drone'):''}<button data-plan-weapons="${escape(route.weaponIds.join(','))}">將未持有項目加入預算</button></div>${sourceLinks(route.sourceIds)}</div></details>`;
 };
 const farmHtml=farm=>{
  const own=ownFarmTotals(progress,farm.missionId,farm.difficulty);
  return `<details class="advice-farm" id="${escape(farm.id)}"><summary><span class="farm-number">${farm.missionId.toUpperCase()}</span><div><strong>${escape(farm.goal)}</strong><small>${escape(farm.stage)} · ${escape(farm.difficulty)}</small></div></summary><div class="advice-route-body"><p><strong>先備條件：</strong>${escape(farm.requirements)}</p><div class="sources">${routeWeapons(farm,weapons).map(weaponLink).join('')}</div><ol>${farm.steps.map(step=>`<li>${escape(step)}</li>`).join('')}</ol><p class="warning">${escape(farm.caution)}</p><p class="farm-own">${own.runs?`你的實測：${own.runs} 場／${own.minutes.toFixed(1)} 分鐘／${own.credits.toLocaleString()} Credits。`:'先試一輪，再用自己的時間與結算收入比較。'}</p><div class="actions">${button('roadmap','本關攻略',farm.missionId)}<button data-use-farm="${escape(farm.id)}">記錄這條路線的收益</button></div>${sourceLinks(farm.sourceIds)}</div></details>`;
 };
 return `<nav class="advice-jumps" aria-label="出擊與養成段落"><a href="#mission-prep">這關帶什麼</a><a href="#early-upgrades">開局先拿什麼</a><a href="#farming-routes">缺錢／素材刷什麼</a></nav><section class="mission-prep" id="mission-prep"><div class="prep-heading"><h2>出擊前先看這關要什麼</h2><label>準備挑戰<select id="advice-mission">${option(missions.map(m=>[m.id,m.id.toUpperCase()+' · '+m.officialName]),mission.id)}</select></label></div><p class="prep-enemies">主要敵人：${escape(mission.enemies.join('、'))}</p><ul class="prep-needs">${equipmentNeeds(mission).map(text=>`<li>${escape(text)}</li>`).join('')}</ul>${mission.warnings.length?`<p class="persistent-warning">${escape(mission.warnings.join(' '))}</p>`:''}<div class="actions">${button('roadmap','看本關打法',mission.id)}${button('weapons','核對自己的武器')}</div><details class="prep-evidence"><summary>建議依據與限制</summary><p>上方為既有逐關攻略的裝備需求。未逐關驗證具名雙槍配置，不用類型或等級直接猜出必勝組合；請搭配本關打法與已持有裝備選用。</p>${sourceLinks(mission.sourceIds)}</details></section><div class="advice-principles">${data.principles.map(row=>`<div><h3>${escape(row.title)}</h3><p>${escape(row.text)}</p></div>`).join('')}</div><section class="advice-section" id="early-upgrades"><h2>開局先拿什麼，玩起來比較順</h2><p class="muted">可選的升級路線，不要求把所有武器買齊。依需求選一條；解鎖後仍要購買。</p>${data.earlyRoutes.map(routeHtml).join('')}</section><section class="advice-section" id="farming-routes"><h2>先分清楚：缺 Credits，還是缺某色 Gems</h2><p class="muted">下列是社群方法與先備條件，沒有套用網路固定時薪。Disaster 通關後才開放；初到該關時的裝備未必能執行後期刷法。</p><div class="starter-economy"><h3>${escape(data.starterEconomy.title)}</h3><p>${escape(data.starterEconomy.text)}</p>${button('resources','算目前購買缺口')}</div>${data.farms.map(farmHtml).join('')}<details class="prep-evidence"><summary>沒有採用的刷法與來源差異</summary><ul>${data.exclusions.map(row=>`<li>${escape(row.text)}</li>`).join('')}</ul><p>Wiki 同頁含舊版本與新版表格；GameFAQs 的評價、難度與配裝也不同。因此不將任何一組收益／秒數當固定值，不帶入個人資源場次估算。</p>${sourceLinks(data.sources.map(row=>row.id))}</details></section><p class="unknown">心得核對 ${escape(data.checkedAt)}；繁中自行整理，未實機驗證。數值預算以各武器已核對欄位為準，未知成本會在規劃器排除並提醒。</p>`;
}
